import { Component, inject } from '@angular/core';
import { RouterLink } from '@angular/router';
import { NgIcon, provideIcons } from '@ng-icons/core';
import { lucidePencil, lucideUserPlus } from '@ng-icons/lucide';
import { HlmAvatarImports } from '@spartan-ng/helm/avatar';
import { HlmBadgeImports, type BadgeVariants } from '@spartan-ng/helm/badge';
import { HlmButtonImports } from '@spartan-ng/helm/button';
import { HlmInputImports } from '@spartan-ng/helm/input';
import { HlmLabelImports } from '@spartan-ng/helm/label';
import { HlmSelectImports } from '@spartan-ng/helm/select';
import { HlmTableImports } from '@spartan-ng/helm/table';
import { HlmTooltipImports } from '@spartan-ng/helm/tooltip';
import { initialsOf } from '../domain/initials';
import type { HeroStatus } from '../domain/hero';
import { RosterViewModel } from './roster.view-model';

/** Status reads through the badge's own variants, so the call site carries no colour classes. */
function statusVariant(status: HeroStatus): BadgeVariants['variant'] {
  switch (status) {
    case 'Active':
      return 'default';
    case 'Injured':
      return 'secondary';
    case 'Reserve':
      return 'outline';
    case 'MIA':
      return 'destructive';
  }
}

/** The roster screen: filter bar, roster table, and summary footer. All state lives in RosterViewModel. */
@Component({
  selector: 'app-heroes',
  imports: [
    RouterLink,
    NgIcon,
    HlmAvatarImports,
    HlmBadgeImports,
    HlmButtonImports,
    HlmInputImports,
    HlmLabelImports,
    HlmSelectImports,
    HlmTableImports,
    HlmTooltipImports,
  ],
  providers: [RosterViewModel, provideIcons({ lucidePencil, lucideUserPlus })],
  template: `
    <div class="flex flex-col gap-6">
      <header class="min-w-0">
        <h1 class="text-2xl font-semibold">Roster</h1>
        <p class="text-sm text-muted-foreground">Example data, for demonstration only.</p>
      </header>

      <div class="flex flex-wrap items-center gap-3">
        <input
          hlmInput
          #search
          type="search"
          class="w-full sm:w-64"
          placeholder="Search name, alias or ID"
          aria-label="Search heroes"
          [value]="vm.query()"
          (input)="vm.setQuery(search.value)"
        />

        <label hlmLabel for="roster-class-filter" class="sr-only">Filter by class</label>
        <hlm-select
          class="w-full sm:w-48"
          [value]="vm.classFilter()"
          [itemToString]="vm.labelFor"
          (valueChange)="vm.setClassFilter($event)"
        >
          <hlm-select-trigger class="w-full" buttonId="roster-class-filter">
            <hlm-select-value placeholder="All classes" />
          </hlm-select-trigger>
          <hlm-select-content *hlmSelectPortal>
            @for (option of vm.classOptions; track option) {
              <hlm-select-item [value]="option">{{ vm.labelFor(option) }}</hlm-select-item>
            }
          </hlm-select-content>
        </hlm-select>

        <a hlmBtn routerLink="/recruit" class="ms-auto">
          <ng-icon name="lucideUserPlus" aria-hidden="true" />
          Recruit
        </a>
      </div>

      <div hlmTableContainer>
        <table hlmTable aria-label="Hero roster">
          <thead hlmTHead>
            <tr hlmTr>
              <th hlmTh scope="col">Hero</th>
              <th hlmTh scope="col">Class</th>
              <th hlmTh scope="col" class="text-end">Power</th>
              <th hlmTh scope="col">Status</th>
              <th hlmTh scope="col">Clearance</th>
              <th hlmTh scope="col"><span class="sr-only">Actions</span></th>
            </tr>
          </thead>
          <tbody hlmTBody>
            @if (vm.rows().length === 0) {
              <tr hlmTr>
                <td hlmTd colspan="6" class="text-center">No heroes match these filters.</td>
              </tr>
            }
            @for (hero of vm.rows(); track hero.id) {
              <tr hlmTr>
                <td hlmTd>
                  <div class="flex items-center gap-3">
                    <hlm-avatar size="sm" aria-hidden="true">
                      <span hlmAvatarFallback>{{ initialsOf(hero.name) }}</span>
                    </hlm-avatar>
                    <div class="min-w-0">
                      <a class="font-medium underline-offset-4 hover:underline" [routerLink]="['/detail', hero.id]">{{
                        hero.name
                      }}</a>
                      <p class="text-xs text-muted-foreground">{{ hero.id }} · {{ hero.alias }}</p>
                    </div>
                  </div>
                </td>
                <td hlmTd>
                  <span hlmBadge variant="secondary">{{ hero.powerClass }}</span>
                </td>
                <td hlmTd class="text-end tabular-nums">{{ hero.powerIndex }}</td>
                <td hlmTd>
                  <span hlmBadge [variant]="statusVariant(hero.status)">{{ hero.status }}</span>
                </td>
                <td hlmTd>{{ hero.clearance }}</td>
                <td hlmTd>
                  <a
                    hlmBtn
                    variant="ghost"
                    size="icon"
                    [routerLink]="['/detail', hero.id]"
                    [attr.aria-label]="'Edit ' + hero.name"
                    [hlmTooltip]="'Edit ' + hero.name"
                  >
                    <ng-icon name="lucidePencil" aria-hidden="true" />
                  </a>
                </td>
              </tr>
            }
          </tbody>
          <tfoot hlmTFoot>
            <tr hlmTr>
              <td hlmTd colspan="6">
                {{ vm.visibleCount() }} of {{ vm.totalCount() }} heroes · sorted by power
              </td>
            </tr>
          </tfoot>
        </table>
      </div>
    </div>
  `,
})
export class Heroes {
  protected readonly vm = inject(RosterViewModel);
  protected readonly initialsOf = initialsOf;
  protected readonly statusVariant = statusVariant;
}
import { Injectable, computed, inject, signal } from '@angular/core';
import { HeroService } from '../domain/hero.service';
import { POWER_CLASSES, type Hero, type PowerClass } from '../domain/hero';

const ALL_CLASSES = 'All';

export type ClassFilter = typeof ALL_CLASSES | PowerClass;

function isClassFilter(value: string | null | undefined): value is ClassFilter {
  return value === ALL_CLASSES || (POWER_CLASSES as readonly string[]).includes(value ?? '');
}

// Owns the roster's filter state and the filtered, sorted rows. Component-scoped, no DOM.
@Injectable()
export class RosterViewModel {
  private readonly heroService = inject(HeroService);
  private readonly heroes = this.heroService.heroes;

  readonly query = signal('');
  readonly classFilter = signal<ClassFilter>(ALL_CLASSES);
  readonly classOptions: readonly ClassFilter[] = [ALL_CLASSES, ...POWER_CLASSES];

  readonly totalCount = computed(() => this.heroes().length);

  // Filters a copy, then sorts by power, highest first. The service's list is shared state and stays untouched.
  readonly rows = computed<readonly Hero[]>(() => {
    const term = this.query().trim().toLowerCase();
    const powerClass = this.classFilter();
    return this.heroes()
      .filter((hero) => powerClass === ALL_CLASSES || hero.powerClass === powerClass)
      .filter(
        (hero) =>
          term === '' || [hero.name, hero.alias, hero.id].some((field) => field.toLowerCase().includes(term)),
      )
      .sort((a, b) => b.powerIndex - a.powerIndex);
  });

  readonly visibleCount = computed(() => this.rows().length);

  readonly labelFor = (value: string): string => (value === ALL_CLASSES ? 'All classes' : value);

  setQuery(value: string): void {
    this.query.set(value);
  }

  setClassFilter(value: string | null | undefined): void {
    this.classFilter.set(isClassFilter(value) ? value : ALL_CLASSES);
  }
}
import { Component, inject } from '@angular/core';
