      await page.getByRole('button', { name: 'Cancel', exact: true }).last().click();
      await page.waitForTimeout(300);
      log.push(`[375] after cancel dialog count=${await page.getByRole('dialog').count()}`);
      await page.getByRole('button', { name: 'Retire', exact: true }).click();
      await page.waitForTimeout(300);
      await page.getByRole('button', { name: 'Retire hero' }).click();
      await page.waitForTimeout(500);
      log.push(`[375] after retire url=${page.url()} errors=${JSON.stringify(errs)}`);
    }
    await ctx.close();
