  await page.goto(srv.origin + '/detail/NOPE', { waitUntil: 'networkidle' });
  log.push(`[1280 unknown] h1=${await page.locator('h1').first().innerText()}`);
  await page.goto(srv.origin + '/detail/HRO-0040', { waitUntil: 'networkidle' });
  log.push(`[1280 injured] deploy disabled=${await page.getByRole('button', { name: 'Deploy' }).isDisabled()} errors=${JSON.stringify(errs)}`);
